examples.template:
MonarchAiAgentCard(
    MonarchAiAgentRef(id: {{agent.id}}, name: {{agent.name}}, role: {{agent.role}}),
    description: {{description}},
    capabilities: [{{capabilities.0}}, {{capabilities.1}}, {{capabilities.2}}],
    tools: [
        MonarchAiAgentTool({{tools.0.name}}, description: {{tools.0.description}}),
        MonarchAiAgentTool({{tools.1.name}}, description: {{tools.1.description}}),
    ],
    dataAccess: [{{dataAccess.0}}, {{dataAccess.1}}],
    owner: {{owner}}
) {
    MonarchButton({{action.label}}, variant: .{{action.variant|raw}}, size: .{{action.size|raw}}) {}
}

examples.code:
MonarchAiAgentCard(
    MonarchAiAgentRef(id: "research", name: "Research agent", role: "Finds and summarises sources"),
    description: "Reads documents in this space and answers with citations to the passages it used.",
    capabilities: ["Summarises documents", "Compares versions", "Cites sources"],
    tools: [
        MonarchAiAgentTool("Search documents", description: "Full-text search in this space"),
        MonarchAiAgentTool("Read file", description: "Opens a document you can already see"),
    ],
    dataAccess: ["Documents in this space", "Comments on those documents"],
    owner: "Alex Morgan"
) {
    MonarchButton("Start a chat", variant: .secondary, size: .sm) {}
}
